# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), ключ сверен с ответами учебника (№245, 246, 251) и вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_15_245_a", r"$t=x-\frac1x$: $t^{2}+2-\frac t2=\frac72\Rightarrow t^{2}-\frac t2-\frac32=0$, $t=\frac32$ или $t=-1$; $x-\frac1x=\frac32\Rightarrow x=2$ или $x=-\frac12$; $x-\frac1x=-1\Rightarrow x^{2}+x-1=0\Rightarrow x=\frac{-1\pm\sqrt5}{2}$ (ответ учебника: $-\frac12;\ 2;\ \frac{-1\pm\sqrt5}{2}$). Ключ содержал $1\pm\sqrt2$",
  k=r"$x = 2$; $x = -\dfrac{1}{2}$; $x = \dfrac{-1+\sqrt{5}}{2}$; $x = \dfrac{-1-\sqrt{5}}{2}$",
  dnew={0: (r"$x = 2$; $x = -\dfrac{1}{2}$", r"Ученик нашёл $t=\frac32$ и $t=-1$, но вернулся к $x$ только для $t=\frac32$; уравнение $x-\frac1x=-1$ даёт ещё два корня $x=\frac{-1\pm\sqrt5}{2}$."),
        1: (r"$x = 2$; $x = -\dfrac{1}{2}$; $x = \dfrac{1+\sqrt{5}}{2}$; $x = \dfrac{1-\sqrt{5}}{2}$", r"Ученик для $t=-1$ записал $x^{2}-x-1=0$ вместо $x^{2}+x-1=0$ (умножая $x-\frac1x=-1$ на $x$, потерял знак у $x$ в правой части)."),
        2: (r"$x = 2$; $x = -\dfrac{1}{2}$; $x = -1+\sqrt{2}$; $x = -1-\sqrt{2}$", r"Ученик умножил $x-\frac1x=-1$ на $2x$ вместо $x$ и получил $x^{2}-1=-2x$, то есть $x=-1\pm\sqrt2$; верно $x^{2}-1=-x$.")})
E("G9_TB_15_251", r"$\frac n{n+3}$: $\frac{3n-7}{2(n+3)-11}=\frac{n+3}n\Rightarrow n^{2}-8n+15=0\Rightarrow n=3$ или $n=5$; дроби $\frac36$ и $\frac58$ (ответ учебника: «$\frac58,\ \frac36$»); в ключе была только $\frac58$",
  k=r"$\dfrac{5}{8}$ или $\dfrac{3}{6}$",
  dnew={0: (r"$\dfrac{5}{8}$", r"Ученик решил $n^{2}-8n+15=0$, но оставил только $n=5$, отбросив $n=3$ из-за сократимости дроби $\frac36$; по условию подходят обе дроби."),
        1: (r"$\dfrac{3}{6}$", r"Ученик оставил только $n=3$ и потерял корень $n=5$ квадратного уравнения $n^{2}-8n+15=0$."),
        2: (r"$\dfrac{8}{5}$ или $\dfrac{6}{3}$", r"Ученик записал обратные дроби (те, что получаются после преобразований), а не искомые исходные дроби $\frac58$ и $\frac36$.")})
E("G9_TB_15_246_б", r"запись $3\dfrac{x+4}{x+16}$ читается как смешанное число «3 целых»; верно $\dfrac{3(x+4)}{x+16}$ (ответ учебника: $\dfrac{3x+12}{x+16}$)",
  k=r"$\dfrac{3(x+4)}{x+16}$",
  dnew={0: (r"$\dfrac{3(x-4)}{x+16}$", r"Ученик разложил $3x^{2}-36x-192=3(x-16)(x+4)$ неверно: перепутал знак корня $-4$ и получил множитель $x-4$."),
        1: (r"$\dfrac{3(x+4)}{x-16}$", r"Ученик сократил не тот множитель: после разложения $\dfrac{3(x-16)(x+4)}{(x-16)(x+16)}$ в знаменателе остаётся $x+16$, а не $x-16$."),
        2: (r"$\dfrac{3(x-16)}{x+16}$", r"Ученик при разложении числителя перепутал корни $16$ и $-4$ и оставил после сокращения множитель $x-16$ вместо $x+4$.")})
